//! Where the sender of a transfer reads its data from.

/// The data of an outgoing transfer: the files of the offer, concatenated.
pub(crate) enum Source {
    /// An in-memory buffer.
    Bytes { data: Vec<u8>, position: usize },
    /// Files on disk.
    #[cfg(not(target_arch = "wasm32"))]
    Files(crate::file_transfer::fs::FilesSource),
    /// Browser files.
    #[cfg(target_arch = "wasm32")]
    Web(crate::file_transfer::web::WebSource),
    /// Generated bytes, for tests and benchmarks that need large transfers
    /// without the memory.
    #[cfg(any(test, feature = "bench"))]
    Pattern { remaining: u64 },
}

impl Source {
    pub(crate) fn bytes(data: Vec<u8>) -> Self {
        Self::Bytes { data, position: 0 }
    }

    /// Reads exactly `len` bytes, the next part of the transfer.
    ///
    /// The engine never asks for more than the offer announced, so reading
    /// fewer means the data changed after the offer was made.
    pub(crate) async fn read(&mut self, len: usize) -> Result<Vec<u8>, String> {
        match self {
            Self::Bytes { data, position } => {
                let end = position
                    .checked_add(len)
                    .filter(|end| *end <= data.len())
                    .ok_or("the data is shorter than announced")?;
                let chunk = data[*position..end].to_vec();
                *position = end;
                Ok(chunk)
            }
            #[cfg(not(target_arch = "wasm32"))]
            Self::Files(files) => files.read(len).await,
            #[cfg(target_arch = "wasm32")]
            Self::Web(files) => files.read(len).await,
            #[cfg(any(test, feature = "bench"))]
            Self::Pattern { remaining } => {
                if (len as u64) > *remaining {
                    return Err("the data is shorter than announced".to_string());
                }
                *remaining -= len as u64;
                Ok(vec![0xa5; len])
            }
        }
    }
}
